package PRACTISE;

public class JavaMath {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
 int x = -100 , y = 200;
 System.out.println("Max of two numbers : " + Math.max(x, y));
 System.out.println("Min of two numbers : " + Math.min(x, y));
 System.out.println("Square root of number : " + Math.sqrt(y));
 System.out.println("Square of numbers : " + Math.pow(x,3));
 System.out.println("Random numbers : " + Math.random());
 System.out.println("Postive number : " + Math.abs(x));
	}

}
